public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Compute the serialized size of the message using the provided buffer
    int size = schema.computeSerializedSize(message, buffer);
    // Create a CodedOutputStream backed by the supplied OutputStream
    CodedOutputStream codedOut = CodedOutputStream.newInstance(out);
    // Write the size prefix as a varint
    codedOut.writeRawVarint32(size);
    // Write the actual message bytes
    schema.writeTo(codedOut, message, buffer);
    // Flush the stream to ensure all bytes are written
    codedOut.flush();
    return size;
