public Mappings diffStructure(String tableName, Mappings mappings) {
    try {
        // Fetch the current mapping for the given index/table
        GetMappingsRequest request = new GetMappingsRequest().indices(tableName);
        GetMappingsResponse response = client.indices().get(request, RequestOptions.DEFAULT);
        MappingMetadata metadata = response.mappings().get(tableName);
        Map<String, Object> sourceMap = metadata.getSourceAsMap();

        // Extract the current properties map
        @SuppressWarnings("unchecked")
        Map<String, Object> currentProps = (Map<String, Object>) sourceMap.get("properties");

        // The history mapping (passed in as 'mappings') should also expose its properties Map
        Map<String, Object> historyProps = mappings.getProperties();

        // Build a new Mappings instance containing only the fields missing in the history
        Mappings diff = new Mappings();
        for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String fieldName = entry.getKey();

            // Skip the special _source configuration to avoid conflicts when updating the index
            if ("_source".equals(fieldName)) {
                continue;
            }

            // Add the property to the diff only if it does not exist in the history mapping
            if (!historyProps.containsKey(fieldName)) {
                diff.addProperty(fieldName, entry.getValue());
            }
        }

        return diff;
    } catch (IOException e) {
        throw new RuntimeException("Failed to compute mapping diff for index: " + tableName, e);
    }
