public boolean equals(final byte[] data, int offset, final int len) {
    // If the internal data array is null, only consider equal if the provided slice is also empty
    if (this.data == null) {
        return data == null ? offset == 0 && len == 0 : offset == 0 && len == 0;
    }

    // If the lengths differ, they cannot be equal
    if (len != this.data.length) {
        return false;
    }

    // Basic bounds check to avoid ArrayIndexOutOfBoundsException
    if (data == null || offset < 0 || offset + len > data.length) {
        return false;
    }

    // Compare byte-by-byte
    for (int i = 0; i < len; i++) {
        if (this.data[i] != data[offset + i]) {
            return false;
        }
    }
    return true;
