    // If it's already a Character, just return it
    if (value instanceof Character) {
        return value;
    }
    // If it's a CharSequence, convert to Character if length == 1
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 0) {
            return null;
        }
        if (cs.length() == 1) {
            return Character.valueOf(cs.charAt(0));
        }
        throw new IllegalArgumentException("Cannot convert CharSequence to Character: string length > 1");
