    // Collect all characters from search strings in a case-insensitive set
    java.util.HashSet<Character> searchSet = new java.util.HashSet<>();
    for (String s : searchStrArray) {
        if (s == null) {
            continue;
        }
        for (int i = 0; i < s.length(); i++) {
            searchSet.add(java.lang.Character.toLowerCase(s.charAt(i)));
