private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new LinkedHashMap<>();
    if(jsonObject == null){
        return content;
    }
    for(Map.Entry<String,JsonElement> entry : jsonObject.entrySet()){
        String key = entry.getKey();
        JsonElement val = entry.getValue();
        Object objVal;
        if(val.isJsonPrimitive()){
            JsonPrimitive prim = val.getAsJsonPrimitive();
            if(prim.isBoolean()){
                objVal = prim.getAsBoolean();
            }else if(prim.isNumber()){
                Number num = prim.getAsNumber();
                // prefer long if no fractional part
                objVal = (num.doubleValue() % 1 == 0) ? num.longValue() : num.doubleValue();
            }else{
                objVal = prim.getAsString();
            }
        }else if(val.isJsonObject()){
            objVal = buildContent(val.getAsJsonObject());
        }else if(val.isJsonArray()){
            List<Object> arr = new ArrayList<>();
            for(JsonElement e : val.getAsJsonArray()){
                if(e.isJsonPrimitive()){
                    JsonPrimitive pe = e.getAsJsonPrimitive();
                    if(pe.isBoolean()){
                        arr.add(pe.getAsBoolean());
                    }else if(pe.isNumber()){
                        Number n = pe.getAsNumber();
                        arr.add((n.doubleValue()%1==0)? n.longValue() : n.doubleValue());
                    }else{
                        arr.add(pe.getAsString());
                    }
                }else if(e.isJsonObject()){
                    arr.add(buildContent(e.getAsJsonObject()));
                }else if(e.isJsonArray()){
                    arr.add(e.getAsJsonArray());
                }else{
                    arr.add(null);
                }
            }
            objVal = arr;
        }else{
            objVal = null;
        }
        content.put(key, objVal);
    }
    // if "ats" key exists, it's already included by the iteration above.
    return content;
}<|return|>

