public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= str.length()) {
                sb.append('\\');
                break;
            }
            char next = str.charAt(++i);
            switch (next) {
                case '\\':
                    sb.append('\\');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case 'u': {
                    if (i + 4 > str.length()) {
                        sb.append("\\u");
                        i--; // keep loop index consistent
                        break;
                    }
                    String hex = str.substring(i + 1, i + 5);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        sb.append("\\u");
                    }
                    i += 4;
                    break;
                }
                default:
                    if (next >= '0' && next <= '7') {
                        int val = next - '0';
                        int digitsUsed = 1;
                        while (digitsUsed < 3 && i + 1 < str.length()) {
                            char d = str.charAt(i + 1);
                            if (d >= '0' && d <= '7') {
                                val = (val << 3) + (d - '0');
                                i++;
                                digitsUsed++;
                            } else {
                                break;
                            }
                        }
                        sb.append((char) val);
                    } else {
                        sb.append(next);
                    }
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}<|return|>

