private String unescapeId(String input){
    if (input == null || input.isEmpty()){
        return input;
    }
    StringBuilder out = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n': out.append('\n'); i++; break;
                case 'r': out.append('\r'); i++; break;
                case 't': out.append('\t'); i++; break;
                case 'b': out.append('\b'); i++; break;
                case 'f': out.append('\f'); i++; break;
                case '\\': out.append('\\'); i++; break;
                case '\'': out.append('\''); i++; break;
                case '\"': out.append('\"'); i++; break;
                case 'x': // hex escape \xHH
                    {
                        int hexDigits = 0;
                        StringBuilder hex = new StringBuilder();
                        int j = i + 2;
                        while (j < len && hexDigits < 2 && Character.isDigit(input.charAt(j)) && "0123456789abcdefABCDEF".indexOf(input.charAt(j)) != -1) {
                            hex.append(input.charAt(j));
                            j++; hexDigits++;
                        }
                        if (hexDigits > 0) {
                            try {
                                int val = Integer.parseInt(hex.toString(), 16);
                                out.append((char) val);
                                i = j - 1;
                            } catch (NumberFormatException ex) {
                                out.append(next); // fallback to literal
                            }
                        } else {
                            out.append(next);
                        }
                    }
                    break;
                case 'u': // unicode escape \uHHHH
                    {
                        int unicodeDigits = 0;
                        StringBuilder uni = new StringBuilder();
                        int j = i + 2;
                        while (j < len && unicodeDigits < 4 && Character.isDigit(input.charAt(j)) && "0123456789abcdefABCDEF".indexOf(input.charAt(j)) != -1) {
                            uni.append(input.charAt(j));
                            j++; unicodeDigits++;
                        }
                        if (unicodeDigits == 4) {
                            try {
                                int val = Integer.parseInt(uni.toString(), 16);
                                out.append((char) val);
                                i = j - 1;
                            } catch (NumberFormatException ex) {
                                out.append(next);
                            }
                        } else {
                            out.append(next);
                        }
                    }
                    break;
                default:
                    // Octal escape up to 3 digits: \NNN
                    if (next >= '0' && next <= '7') {
                        StringBuilder oct = new StringBuilder().append(next);
                        int count = 1;
                        int j = i + 2;
                        while (j < len && count < 3 && input.charAt(j) >= '0' && input.charAt(j) <= '7') {
                            oct.append(input.charAt(j));
                            j++; count++;
                        }
                        try {
                            int val = Integer.parseInt(oct.toString(), 8);
                            out.append((char) val);
                            i = j - 1;
                        } catch (NumberFormatException ex) {
                            out.append(next);
                        }
                    } else {
                        // Default: just drop the backslash and keep next char
                        out.append(next);
                        i++;
                    }
                    break;
            }
        } else {
            out.append(c);
        }
    }
    return out.toString();
