        return;
    }
    int i = nameStart;
    while (i < name.length()){
        // Skip any leading whitespace.
        while (i < name.length() && Character.isWhitespace(name.charAt(i))){
            i++;
        }
        if (i >= name.length()){
            break;
        }
        // Capture the first character of the current word.
        char c = name.charAt(i);
        if (Character.isLetter(c)){
            buf.append(Character.toUpperCase(c)).append('.');
