private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // A null or empty set cannot contain a clique other than the trivial case
    if (vertices == null || vertices.isEmpty() || vertices.size() == 1) {
        return true;
    }
    // For every pair of distinct vertices, check that an edge exists.
    for (V v : vertices) {
        for (V w : vertices) {
            if (v == w) {
                continue;
            }
            if (!graph.containsEdge(v, w)) {
                // For directed graphs might also want to check the opposite direction,
                // but a clique is usually defined on undirected graphs.
                return false;
            }
        }
    }
    return true;
}<|return|>

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    if (keys.isEmpty()) {
        return lowerBounds;
    }
    // Create a sorted copy of the keys
    List<K> sorted = new ArrayList<>(keys);
    Collections.sort(sorted, Comparator.naturalOrder());
    for (K key : keys) {
        int index = Collections.binarySearch(sorted, key);
        if (index < 0) {
            // Key not found: insertion point gives number of smaller elements
            index = -index - 1;
        } else {
            // Key found: move left to find the first occurrence
            while (index > 0 && sorted.get(index - 1).compareTo(key) == 0) {
                index--;
            }
        }
        lowerBounds.add(index);
    }
    return lowerBounds;
