public static String applyRelativePath(String path, String relativePath) {
    // Split the base path into parts
    String[] baseParts = path.split("/");
    // Determine if the base path ends with a file segment (i.e., not ending with '/')
    boolean endsWithFile = !path.endsWith("/") && path.length() > 0;
    // Prepare a list to act as the stack of path components
    java.util.ArrayList<String> stack = new java.util.ArrayList<>();
    // Keep the leading empty part if the path starts with '/'
    if (baseParts.length > 0 && baseParts[0].isEmpty()) {
        stack.add(""); // represents leading '/'
    }
    // Add all directory components, excluding the potential file at the end
    int endIndex = baseParts.length;
    if (endsWithFile && endIndex > 0) {
        endIndex--; // ignore the last segment (file)
    }
    for (int i = stack.isEmpty() ? 0 : 1; i < endIndex; i++) {
        if (!baseParts[i].isEmpty() && !baseParts[i].equals(".")) {
            stack.add(baseParts[i]);
        }
    }

    // Process the relative path parts
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            // Skip empty or current directory references
            continue;
        } else if (part.equals("..")) {
            // Move up one level if possible
            if (stack.size() > (stack.isEmpty() || stack.get(0).isEmpty() ? 1 : 0)) {
                stack.remove(stack.size() - 1);
            }
        } else {
            // Normal path segment
            stack.add(part);
        }
    }

    // Build the resulting path string
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < stack.size(); i++) {
        String seg = stack.get(i);
        if (seg.isEmpty()) {
            // Leading slash
            result.append('/');
        } else {
            if (result.length() > 0 && result.charAt(result.length() - 1) != '/') {
                result.append('/');
            }
            result.append(seg);
        }
    }

    // If result is empty, return "." (current directory)
    return result.length() == 0 ? "." : result.toString();
