protected void append(LoggingEvent event) {
    // Guard against no connected clients
    if (clientStreams == null || clientStreams.isEmpty()) {
        return;
    }

    // Format the event using the appender's layout if one is set
    String formatted = (layout == null) ? event.getRenderedMessage() : layout.format(event);

    // Send the message to each connected client
    for (OutputStream out : clientStreams) {
        try {
            // Convert to bytes using platform default encoding; adjust if a specific charset is required
            byte[] data = formatted.getBytes();
            out.write(data);
            out.flush();
        } catch (IOException ioEx) {
            // If a writer has an error handler (e.g., Log4j's ErrorHandler), report the failure
            if (errorHandler != null) {
                errorHandler.error("Failed to write log message to client", ioEx, ErrorCode.WRITE_FAILURE);
            } else {
                // Fallback: print to standard error if no error handler is present
                System.err.println("Failed to write log message to client: " + ioEx.getMessage());
            }
        }
    }
