    // Parse all snapshots from the file
    List<ThreadSnapshot> allSnapshots = parseFromFile(file);
    List<ThreadSnapshot> filtered = new ArrayList<>(allSnapshots.size());

    // Iterate over snapshots and keep only those that fall into any of the specified time ranges
    for (ThreadSnapshot snapshot : allSnapshots) {
        long timestamp = snapshot.getTimestamp(); // assume snapshots expose their capture time
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            long start = range.getStartTime();
            long end   = range.getEndTime();
            if (timestamp >= start && timestamp <= end) {
                filtered.add(snapshot);
                break; // no need to check the remaining ranges
